const img={hero:"/assets/dclPfBZrAjGadJzr.webp",wash:"/assets/iZajOBxckRqOnRSZ.webp",track:"/assets/ZGKdDxSkBuQRGHzG.webp",kitchen:"/assets/ecdPHtBOuKRbeJtC.webp"};
const commonFaq:[string,string][]=[["Takip linki nasıl çalışır?","Servis kaydınız açıldıktan sonra size WhatsApp üzerinden özel bir bağlantı iletilir. Bağlantıdan işlem durumunu takip edebilirsiniz."],["Aynı gün servis mümkün mü?","Konya içindeki günlük planlama ve ekibin uygunluğuna göre aynı gün servis hedeflenir. Net bilgi talebinizde paylaşılır."]];
const serviceGuides:Record<string,{guide:GuideSection[];faqs:[string,string][]}>={
 "Çamaşır Makinesi":{guide:[{title:"Çamaşır makinesi hangi belirtilerde servis ister?",text:"Makinenin su almaması, programı yarıda bırakması, sıkma sırasında aşırı sallanması veya tamburdan metalik ses gelmesi farklı arıza gruplarına işaret edebilir. Su boşaltmama sorununda filtre ve tahliye hattı; sıkmama sorununda yük dengesi, kapak kilidi ve motor grubu değerlendirilir. Hata kodunu, programı ve arızanın ne zaman başladığını not etmeniz ön incelemeyi kolaylaştırır."},{title:"Servis öncesi güvenli kontroller",text:"Fişi çekmeden cihazın arka kapağını veya elektrik aksamını açmayın. Kullanıcı olarak su vanasının açık olduğunu, tahliye hortumunun kıvrılmadığını ve tamburun aşırı yüklenmediğini kontrol edebilirsiniz. Filtre temizliği için kullanım kılavuzundaki adımları izleyin; içeride su varsa zemini koruyun. Yanık kokusu, kaçak veya sigorta attırma varsa cihazı tekrar çalıştırmadan servis desteği alın."},{title:"İnceleme, işlem süresi ve fiyatlandırma",text:"Servis planlamasında marka, model, arıza belirtisi ve bulunduğunuz ilçe birlikte değerlendirilir. Basit tıkanıklık, ayar veya bağlantı sorunları aynı ziyarette çözülebilir. Pompa, rezistans, kart, amortisör veya kapak kilidi gibi parçalarda süre model ve parça teminine göre değişir. Fiyat; arıza tespiti, işçilik, parça ve ulaşım koşulları netleştikten sonra paylaşılır; onayınız olmadan parça değişimi yapılmaz."},{title:"Ne zaman gecikmeden servis çağırmalı?",text:"Su kaçağı, kablo veya prizde ısınma, yanık kokusu, tamburun sıkışması ve cihazın sigorta attırması bekletilmemesi gereken belirtilerdir. Aynı sorun kısa aralıklarla tekrarlıyorsa geçici reset işlemleri yerine kök nedenin incelenmesi gerekir. Karatay, Meram ve Selçuklu için cihaz bilgisiyle WhatsApp’tan yazabilir, servis kaydı açıldığında süreci takip bağlantısından izleyebilirsiniz."}],faqs:[["Çamaşır makinesi su almıyorsa ne kontrol edilir?","Su vanasının açık, giriş hortumunun kıvrılmamış ve filtrede belirgin tıkanıklık olmadığını güvenli biçimde kontrol edebilirsiniz. Sorun sürerse servis kaydı oluşturun."],["Çamaşır makinesi neden sıkma yapmaz?","Dengesiz yük, tahliye problemi, kapak kilidi veya motor grubu etkilenmiş olabilir. Cihazı zorlamadan arıza belirtisini paylaşın."],["Çamaşır makinesi servisinde parça değişimi öncesi bilgi verilir mi?","İnceleme sonrası gerekli işlem ve parça ihtiyacı açıklanır; onayınız alınmadan parça değişimi yapılmaz."],...commonFaq]},
 "Bulaşık Makinesi":{guide:[{title:"Bulaşık makinesi arızası nasıl anlaşılır?",text:"Bulaşıkların kirli veya lekeli çıkması, makinenin suyu boşaltmaması, programın uzaması ve tabanda su kalması sık görülen belirtilerdir. Su alma ve tahliye hatları, filtre, pompa, püskürtme kolları, rezistans ve elektronik kontrol grubu farklı kontroller gerektirir. Kötü koku tek başına büyük bir arıza anlamına gelmeyebilir; ancak su birikmesi veya alışılmadık sesle birlikteyse servis değerlendirmesi gerekir."},{title:"Kullanıcının yapabileceği güvenli kontroller",text:"Elektrik bağlantısını ve su vanasını kontrol edin; müdahale öncesinde fişi çekin. Filtreleri kullanım kılavuzuna göre temizleyin, püskürtme kollarının deliklerinde yemek artığı olup olmadığına bakın ve tahliye hortumunun ezilmediğinden emin olun. Alt kapağı, pompayı veya kabloları sökmeyin. Su zemine taşıyorsa cihazı yeniden çalıştırmak yerine su vanasını kapatıp destek isteyin."},{title:"Servis süreci ve süreyi etkileyen etkenler",text:"İlk mesajda marka, model, hata kodu, suyun nerede kaldığı ve programın hangi aşamada durduğu belirtilmelidir. Filtre, hortum veya ayar kaynaklı sorunlar aynı ziyarette çözülebilir. Pompa, rezistans, kart veya su alma valfi gibi parçalarda süre; cihaz modeline ve parçanın temin durumuna bağlıdır. Ücret, inceleme ve parça gereksinimi açıklandıktan sonra netleştirilir."},{title:"Ne zaman servis çağırmalısınız?",text:"Su kaçağı, elektrik kokusu, sigorta attırma, pompanın sürekli çalışması veya cihazın suyu boşaltmaması bekletilmemelidir. Aynı arıza tekrar ediyorsa deterjan miktarını değiştirmek sorunu çözmeyebilir. Eşli Teknik, Karatay, Meram ve Selçuklu için servis planlamasını cihaz ve arıza bilgisine göre yapar; kayıt açıldığında güncellemeler online takip bağlantınıza işlenir."}],faqs:[["Bulaşık makinesinin içinde su kalıyorsa ne yapılır?","Cihazı zorlamadan filtreyi, tahliye hortumunu ve görünür tıkanıklıkları kılavuza uygun biçimde kontrol edin. Su kalmaya devam ederse pompa ve tahliye hattı için servis isteyin."],["Bulaşık makinesi neden temiz yıkamaz?","Filtre, püskürtme kolları, su sıcaklığı, deterjan kullanımı veya rezistans etkili olabilir. Belirtinin programın hangi aşamasında ortaya çıktığını paylaşın."],["Bulaşık makinesi servisinde aynı gün planlama yapılır mı?","Konya içindeki günlük planlama ve ekip uygunluğuna göre aynı gün hedeflenebilir; net zaman servis talebi sırasında paylaşılır."],...commonFaq]},
 "Buzdolabı":{guide:[{title:"Buzdolabı soğutmuyorsa olası nedenler",text:"Buzdolabının yeterince soğutmaması; kapı contasının hava kaçırması, hava kanallarının kapanması, fan veya sensör sorunu, termostat ayarı ya da kompresör çalışma problemiyle ilişkili olabilir. Motorun aralıksız çalışması, iç bölümde buzlanma, su birikmesi ve alışılmadık sesler de önemsenmelidir. Gıdaların bozulmasını önlemek için arıza belirtisini fark ettiğinizde gecikmeden bilgi verin."},{title:"Servis öncesi güvenli gözlemler",text:"Cihazın etrafında hava dolaşımı için yeterli boşluk olduğunu, kapının tam kapandığını ve sıcaklık ayarının yanlışlıkla değişmediğini kontrol edebilirsiniz. İç duvarlardaki yoğun buzlanmayı kesici aletlerle kazımayın; gaz hattına zarar verebilirsiniz. Kompresör kapağını açmayın ve soğutucu gaz müdahalesi yapmayın. Su akıntısı varsa zemini koruyup cihazı güvenli biçimde gözlemleyin."},{title:"İnceleme ve fiyatlandırma nasıl belirlenir?",text:"Buzdolabı arızalarında marka-model, soğutma seviyesi, buzlanma durumu ve motorun çalışma davranışı önemlidir. Conta veya ayar gibi işlemler aynı ziyarette tamamlanabilir. Fan, sensör, kart, termostat veya kompresörle ilgili işlemlerde parça ve uygulama süresi modele göre değişir. Fiyat; tespit, işçilik ve gerekiyorsa parça maliyeti birlikte değerlendirilerek onayınıza sunulur."},{title:"Hangi belirtilerde beklememeli?",text:"Kompresörün hiç çalışmaması, sürekli devrede kalması, yanık kokusu, elektrik attırma, yoğun su kaçağı veya hızlı ısı artışı acil değerlendirme gerektirir. Buzdolabını tekrar tekrar kapatıp açmak yerine model ve belirti bilgisini paylaşın. Karatay, Meram ve Selçuklu servis planlamasında takip bağlantısıyla işlem aşamalarını görüntüleyebilirsiniz."}],faqs:[["Buzdolabı soğutmuyorsa fişi çekilmeli mi?","Yanık kokusu, elektrik kaçağı veya sigorta attırma varsa cihazı kullanmayın. Diğer durumlarda sıcaklık, kapı ve hava dolaşımı gözlemlerini paylaşarak servis yönlendirmesi alın."],["Buzdolabındaki buzlanma arıza mıdır?","Tek başına her buzlanma aynı anlama gelmez; conta, hava kanalı, sensör veya defrost sistemi incelenebilir. Buzu kesici aletle kazımayın."],["Buzdolabı tamiri ne kadar sürer?","Ayar, conta veya basit bağlantı işlemleri aynı ziyarette tamamlanabilir; parça ve soğutma sistemi işlemlerinde süre model ve parçaya göre değişir."],...commonFaq]},
 "Fırın":{guide:[{title:"Fırın arızalarında en sık görülen belirtiler",text:"Fırının geç ısınması, hiç ısıtmaması, sıcaklığı koruyamaması, fanın çalışmaması veya ekranda hata kodu görülmesi farklı bileşenlerin kontrolünü gerektirir. Rezistans, termostat, fan motoru, sensör, kapak contası ve kontrol kartı fırın performansını etkileyebilir. Pişirme süresinin uzaması veya yemeğin bir tarafının fazla kızarması da ısı dağılımı sorununa işaret edebilir."},{title:"Güvenli ilk kontroller",text:"Fırının enerji bağlantısını, saat/program ayarını ve sıcaklık seçimini kontrol edin. Gazlı modellerde gaz kokusu varsa vanayı kapatın, ortamı havalandırın ve elektrik düğmelerine dokunmadan yetkili destek alın. Rezistans, fan veya paneli sökmeyin. Camda çatlak, kapakta kapanmama veya kabloda ısınma fark ederseniz cihazı kullanmayı bırakın."},{title:"Servis süresi ve fiyatlandırma",text:"Model, enerji türü, hata kodu ve arızanın ısıtma mı yoksa kontrol mü kaynaklı olduğu servis planlamasını belirler. Rezistans, termostat veya conta gibi parçalar uygunluk durumuna göre aynı ziyarette değişebilir. Kart ve fan grubu işlemlerinde parça temini süreyi etkileyebilir. Ücret, inceleme sonucunda işçilik ve parça kalemleri açıklanarak paylaşılır."},{title:"Ne zaman servis çağırmalı?",text:"Gaz kokusu, elektrik çarpması, sigorta attırma, duman, yanık kokusu veya kapak camında hasar varsa fırını kullanmayın. Isıtma sorunu küçük görünse bile sürekli çalıştırmak enerji tüketimini artırabilir ve başka parçalara yük bindirebilir. Eşli Teknik, Konya’da servis talebini cihaz bilgisi ve ilçe ile alarak süreci takip edilebilir şekilde planlar."}],faqs:[["Fırın ısıtmıyorsa kullanıcı neyi kontrol edebilir?","Enerji bağlantısı, saat/program ayarı ve sıcaklık seçimi kontrol edilebilir. Rezistans veya termostatı sökmeyin; sorun sürerse servis isteyin."],["Fırın tamiri aynı gün tamamlanır mı?","Basit bağlantı, ayar veya uygun parça işlemleri aynı ziyarette tamamlanabilir. Kart veya özel parça gereken durumlarda süre değişebilir."],["Gazlı fırında gaz kokusu varsa ne yapılmalı?","Gaz vanasını kapatın, ortamı havalandırın ve elektrik düğmelerine dokunmadan yetkili destek alın. Cihazı kullanmaya devam etmeyin."],...commonFaq]},
 "Ocak":{guide:[{title:"Ocak arızasının belirtileri",text:"Ocağın ateşlememesi, düğmenin takılması, alevin düzensiz yanması, elektrikli gözün ısınmaması veya ateşlemenin sürekli devam etmesi servis gerektirebilir. Gazlı ocaklarda alev rengi ve gaz kokusu; elektrikli modellerde kablo, göz ve kontrol grubu önemlidir. Belirtiyi hangi gözde ve ne zaman gördüğünüzü paylaşmanız doğru yönlendirme sağlar."},{title:"Güvenli kontrol ve kullanım uyarısı",text:"Gaz kokusu varsa önce gaz vanasını kapatın, pencereyi açın ve kıvılcım oluşturabilecek düğmelere dokunmayın. Elektrikli ocakta fişi ve sigortayı güvenli biçimde kapatın. Enjektör, gaz hortumu, ateşleme modülü veya cam yüzey üzerinde sökme işlemi yapmayın. Islak yüzey, kırık cam veya gevşek düğme varsa cihazı kullanmadan servis desteği alın."},{title:"İşlem süresi ve fiyat mantığı",text:"Ocak servisinde marka-model, gazlı veya elektrikli oluşu, arızalı göz ve güvenlik belirtileri değerlendirilir. Düğme, ateşleme bujisi veya bağlantı gibi işlemler uygun parça varsa aynı ziyarette tamamlanabilir. Cam, kontrol modülü veya gaz grubu işlemlerinde temin süresi değişebilir. Fiyat, tespit ve gerekli parça/işçilik kalemleri açıklandıktan sonra onayınıza sunulur."},{title:"Hangi durumda beklemeyin?",text:"Gaz kokusu, sarı veya düzensiz alev, sürekli kıvılcım, elektrik çarpması, cam çatlağı ve sigorta attırma belirtilerinde ocağı kullanmayın. Kendi başınıza gaz bağlantısını değiştirmeyin. Konya’nın Karatay, Meram ve Selçuklu ilçelerinde servis talebinizi WhatsApp’tan iletebilir, planlama ve işlem durumunu takip bağlantısından izleyebilirsiniz."}],faqs:[["Ocak ateşlemiyorsa ne kontrol edilir?","Gaz vanası, elektrik bağlantısı ve düğme konumu gözlemlenebilir; ateşleme sistemini sökmeyin. Gaz kokusu varsa cihazı kullanmadan destek alın."],["Ocakta sarı alev neden olur?","Hava-gaz karışımı, enjektör veya yanma sistemiyle ilgili bir sorun olabilir. Ocağı kullanmayı bırakıp güvenli biçimde servis isteyin."],["Ocak camı çatladıysa kullanılabilir mi?","Hayır. Cam çatlağı güvenlik riski oluşturabilir; cihazı kullanmayın ve model bilgisiyle servis yönlendirmesi alın."],...commonFaq]},
 "Kurutma Makinesi":{guide:[{title:"Kurutma makinesi neden kurutmaz?",text:"Kurutma süresinin uzaması, çamaşırların nemli kalması, cihazın ısıtmaması veya tamburun dönmemesi; filtre, hava kanalı, yoğuşma haznesi, rezistans, sensör ya da motor grubuyla ilgili olabilir. Programın çamaşır miktarına uygun seçilmemesi de performansı etkiler. Hata kodu ve cihazın kaç dakika sonra durduğu servis ön değerlendirmesine yardımcı olur."},{title:"Servis öncesi güvenli kontroller",text:"Tiftik filtresini ve su haznesini kullanım kılavuzuna göre temizleyin; yoğuşmalı modellerde hava akışını kapatan birikinti olup olmadığını gözlemleyin. Cihazı aşırı doldurmayın ve havalandırma boşluklarını kapatmayın. Fişi çekmeden gövdeyi açmayın. Yanık kokusu, aşırı ısınma veya tamburdan sürtme sesi varsa cihazı çalıştırmayın."},{title:"Süre ve fiyatlandırma nasıl değişir?",text:"Filtre, hazne, hava akışı veya program ayarı kaynaklı sorunlar aynı ziyarette çözülebilir. Rezistans, termik, nem sensörü, kayış, motor veya elektronik kart arızalarında model ve parça temini belirleyicidir. Fiyat, arıza tespiti sonrasında işçilik ve parça ihtiyacına göre açıklanır. İşleme başlamadan önce kapsam ve tahmini süre hakkında bilgi verilir."},{title:"Ne zaman teknik destek alınmalı?",text:"Cihazın ısıtmaması, aşırı ısınması, sigorta attırması, yanık kokusu, tamburun dönmemesi veya aynı programda sürekli durması bekletilmemelidir. Filtre temizliğine rağmen performans düzelmiyorsa cihazı zorlamayın. Eşli Teknik, Konya’da cihaz, model ve ilçe bilgisiyle servis kaydınızı alır; işlem aşamalarını online takip etmenizi sağlar."}],faqs:[["Kurutma makinesi ısıtmıyorsa ne yapılır?","Filtre, su haznesi ve program seçimini kılavuza göre kontrol edin. Rezistans veya termik gruba müdahale etmeyin; sorun devam ederse servis isteyin."],["Kurutma makinesi neden uzun sürer?","Aşırı yük, tıkalı filtre, hava akışı, nem sensörü veya ısıtma sistemi etkili olabilir. Çamaşır miktarı ve program bilgisini paylaşın."],["Kurutma makinesi servisinde parça değişimi nasıl belirlenir?","Model ve arıza tespitinden sonra gerekli parça, işlem kapsamı ve süre açıklanır; onayınız alınmadan değişim yapılmaz."],...commonFaq]}
};
const service=(name:string,slug:string,lead:string,issues:string[],image:string):Data=>{const detail=serviceGuides[name];return {name,eyebrow:`KONYA ${name.toUpperCase()} TAMİRİ`,title:`Konya ${name} Tamiri | Eşli Teknik`,desc:`Konya’da ${name.toLocaleLowerCase("tr-TR")} tamiri için Eşli Teknik’e WhatsApp’tan ulaşın. Arıza bilgisi, servis planı ve online iş takibiyle destek alın.`,lead,image,issues,copy:[`${name} arızaları günlük düzeni doğrudan etkileyebilir. İlk mesajınızda cihazın modelini, yaşadığınız sorunu ve mümkünse kısa bir video bilgisini paylaşmanız servis planlamasını hızlandırır.`,`İnceleme sonrasında yapılacak işlem ve parça ihtiyacı anlaşılır biçimde paylaşılır. Servis kaydınız oluşturulduğunda, güncellemeleri size iletilen özel takip bağlantısından görüntüleyebilirsiniz.`],faqs:serviceFaqs[name]??detail?.faqs??[[`${name} için nasıl servis kaydı açabilirim?`,`WhatsApp üzerinden cihaz türünü, arıza belirtisini ve bulunduğunuz ilçeyi yazmanız yeterlidir.`],...commonFaq],maintenance:deviceCare[name],guide:detail?.guide};};
