const districtDetails:Record<string,{lead:string;issues:string[];copy:string[];guide:GuideSection[];faqs:[string,string][]}>={
 Karatay:{lead:"Karatay’da çamaşır makinesi, buzdolabı, bulaşık makinesi ve diğer ev cihazlarınız için servis talebinizi WhatsApp’tan iletebilirsiniz.",issues:["Çamaşır ve bulaşık makinesi arızaları","Buzdolabı ve derin dondurucu sorunları","Fırın, ocak ve davlumbaz servis desteği","Su sebili ve küçük ev aletleri için ön değerlendirme"],copy:["Cihazın markasını, modelini ve yaşadığınız sorunu yazmanız ilk yönlendirme için yeterlidir. Karatay’daki açık adresinizi ve uygun olduğunuz zaman aralığını da paylaşırsanız servis planı daha kolay netleşir.","Kayıt oluşturulduğunda size özel takip bağlantısı iletilir. Servis öncesinde yanık kokusu, su kaçağı veya sigorta attırma varsa cihazı kullanmayın."],guide:[{title:"Karatay’da hangi hizmetleri alabilirsiniz?",text:"Çamaşır makinesi, bulaşık makinesi, buzdolabı, derin dondurucu, fırın, ocak, davlumbaz ve su sebili için ilgili cihaz rehberlerini inceleyerek arızanızı daha doğru tanımlayabilirsiniz."},{title:"Servis talebi nasıl oluşturulur?",text:"WhatsApp mesajınıza cihaz türünü, marka-model bilgisini, arıza belirtisini ve Karatay’daki açık adresinizi ekleyin. Uygunluk bilgisi paylaşıldıktan sonra servis süreci başlatılır."}],faqs:districtFaqs.Karatay},
 Meram:{lead:"Meram’da evinizdeki beyaz eşya veya küçük ev aleti için arıza bilgilerinizi paylaşarak servis planlaması hakkında bilgi alabilirsiniz.",issues:["Çamaşır makinesi ve kurutma makinesi arızaları","Buzdolabı, derin dondurucu ve su sebili sorunları","Bulaşık makinesi ve ankastre cihaz desteği","Arıza belirtisine göre cihaz özelinde yönlendirme"],copy:["Meram servis talebinizde cihazın hangi belirtiyi gösterdiğini, modelini ve bulunduğunuz mahalleyi yazın. Fotoğraf veya hata kodu varsa mesajınıza ekleyebilirsiniz.","İnceleme öncesinde cihazı açarak parça sökmeyin. Su kaçağı, duman, yanık kokusu veya elektrik riski fark ederseniz cihazı kullanmayı bırakın; kayıt sonrası işlemleri takip bağlantısından izleyebilirsiniz."],guide:[{title:"Meram’da hangi cihazlar için destek alabilirsiniz?",text:"Çamaşır, kurutma ve bulaşık makineleri; buzdolabı, derin dondurucu, fırın, ocak ve davlumbaz için cihaz türüne özel servis sayfalarından bilgi alabilirsiniz."},{title:"Meram servis kaydı için hangi bilgiler gerekli?",text:"Marka-model, arızanın kısa açıklaması, varsa hata kodu, mahalle ve açık adres bilgisi servis talebinin doğru yönlendirilmesine yardımcı olur."}],faqs:districtFaqs.Meram},
 Selçuklu:{lead:"Selçuklu’da beyaz eşya ve ankastre cihaz arızaları için cihaz bilgilerinizi göndererek servis sürecini başlatabilirsiniz.",issues:["Çamaşır, bulaşık ve kurutma makinesi servisleri","Buzdolabı ve derin dondurucu arızaları","Fırın, ocak ve davlumbaz desteği","Marka-model ve hata koduna göre ön değerlendirme"],copy:["Selçuklu’dan servis isterken cihaz türünü, marka-model bilgisini, arızanın ne zaman başladığını ve açık adresinizi belirtin. Bu bilgiler, talebinizin doğru cihaz rehberine yönlendirilmesini sağlar.","Servis kaydı açıldığında işlem durumunu size iletilen bağlantıdan takip edebilirsiniz. Gaz, elektrik, su veya soğutma sistemine kendi başınıza müdahale etmeyin."],guide:[{title:"Selçuklu’da hangi cihazlara servis verilir?",text:"Çamaşır ve kurutma makineleri, bulaşık makineleri, buzdolapları, derin dondurucular, fırınlar, ocaklar ve davlumbazlar için ilgili servis sayfalarını inceleyebilirsiniz."},{title:"Selçuklu’da servis talebi nasıl ilerler?",text:"Cihaz ve arıza bilgisi alındıktan sonra uygunluk değerlendirilir. Açık adres ve tercih ettiğiniz zaman aralığı netleştirildiğinde servis planı size bildirilir."}],faqs:districtFaqs.Selçuklu}
};
const district=(name:string,image:string):Data=>{const d=districtDetails[name];return {name,eyebrow:`${name.toUpperCase()} TEKNİK SERVİS`,title:`${name} Beyaz Eşya Servisi | Eşli Teknik Konya`,desc:`${name}’da beyaz eşya ve küçük ev aletleri servisi için Eşli Teknik’e ulaşın. Cihaz türü, arıza ve mahalle bilgisiyle servis planınızı netleştirin.`,lead:d.lead,image,issues:d.issues,copy:d.copy,faqs:[...d.faqs,...commonFaq],guide:d.guide};};
pages["/karatay/"]=district("Karatay",img.hero);
pages["/meram/"]=district("Meram",img.kitchen);
pages["/selcuklu/"]=district("Selçuklu",img.track);
