 const deviceBrandLists:Record<string,string[]>={"Çamaşır Makinesi":["Altus","Arçelik","Beko","Bosch","Electrolux","Hoover","Profilo","Regal","Samsung","Siemens","Silverline","Teka","Vestel"],"Bulaşık Makinesi":["Altus","Arçelik","Beko","Bosch","Electrolux","Franke","Hoover","Profilo","Regal","Samsung","Siemens","Silverline","Teka","Vestel"],"Kurutma Makinesi":["Altus","Arçelik","Beko","Bosch","Electrolux","Hoover","Profilo","Regal","Samsung","Siemens","Silverline","Teka","Vestel"],"Fırın":["Altus","Arçelik","Beko","Bosch","Electrolux","Franke","Hoover","Kumtel","Profilo","Regal","Samsung","Siemens","Silverline","Şenocak","Teka","Vestel"],"Ocak":["Altus","Arçelik","Beko","Bosch","Electrolux","Franke","Hoover","Kumtel","Profilo","Regal","Samsung","Siemens","Silverline","Şenocak","Teka","Vestel"],"Buzdolabı":["Altus","Arçelik","Beko","Bosch","Electrolux","Franke","Hoover","Kumtel","Profilo","Regal","Samsung","Siemens","Silverline","Teka","Uğur Soğutma","Vestel"],"Elektrikli Süpürge":["Arçelik","Arnica","Beko","Bosch","Electrolux","Hoover","Philips","Profilo","Regal","Rowenta","Samsung","Siemens","Vestel"],"Davlumbaz":["Altus","Arçelik","Beko","Bosch","Electrolux","Franke","Hoover","Kumtel","Profilo","Regal","Samsung","Siemens","Silverline","Şenocak","Teka","Vestel"],"Derin Dondurucu":["Altus","Arçelik","Beko","Bosch","Electrolux","Profilo","Regal","Siemens","Teka","Uğur Soğutma","Vestel"],"Su Sebili":["Altus","Arçelik","Beko","Bosch","Electrolux","Profilo","Samsung","Siemens","Şenocak","Teka","Uğur Soğutma","Vestel"]};
 const brandPaths:Record<string,string>={"Altus":"/altus-servisi-konya/","Arçelik":"/arcelik-servisi-konya/","Arnica":"/arnica-servisi-konya/","Beko":"/beko-servisi-konya/","Bosch":"/bosch-servisi-konya/","Electrolux":"/electrolux-servisi-konya/","Franke":"/franke-servisi-konya/","Hoover":"/hoover-servisi-konya/","Kumtel":"/kumtel-servisi-konya/","Philips":"/philips-servisi-konya/","Profilo":"/profilo-servisi-konya/","Regal":"/regal-servisi-konya/","Rowenta":"/rowenta-servisi-konya/","Samsung":"/samsung-servisi-konya/","Siemens":"/siemens-servisi-konya/","Silverline":"/silverline-servisi-konya/","Şenocak":"/senocak-servisi-konya/","Teka":"/teka-servisi-konya/","Uğur Soğutma":"/ugur-sogutma-servisi-konya/","Vestel":"/vestel-servisi-konya/"};
	const brandDevicePaths:Record<string,{name:string;href:string;summary:string}[]>={"Çamaşır":[{name:"Çamaşır Makinesi",href:"/camasir-makinesi-tamiri-konya/",summary:"Su almama, sıkma, kapak ve motor belirtileri."}],"Bulaşık":[{name:"Bulaşık Makinesi",href:"/bulasik-makinesi-tamiri-konya/",summary:"Tahliye, yıkama, su alma ve program sorunları."}],"Kurutma":[{name:"Kurutma Makinesi",href:"/kurutma-makinesi-tamiri-konya/",summary:"Isıtma, tambur dönmesi ve nemli bırakma belirtileri."}],"Buzdolabı":[{name:"Buzdolabı",href:"/buzdolabi-tamiri-konya/",summary:"Soğutmama, buzlanma, ses ve su akıtma belirtileri."}],"Fırın/Ocak":[{name:"Fırın",href:"/firin-tamiri-konya/",summary:"Isıtma, fan, sıcaklık ve panel sorunları."},{name:"Ocak",href:"/ocak-tamiri-konya/",summary:"Ateşleme, göz, alev ve düğme sorunları."}],"Davlumbaz":[{name:"Davlumbaz",href:"/davlumbaz-tamiri-konya/",summary:"Çekiş, motor, filtre ve aydınlatma sorunları."}],"Derin dondurucu":[{name:"Derin Dondurucu",href:"/derin-dondurucu-tamiri-konya/",summary:"Dondurmama, buzlanma ve sıcaklık sorunları."}],"Su sebili":[{name:"Su Sebili",href:"/su-sebili-tamiri-konya/",summary:"Soğutma, ısıtma, su akışı ve kaçak belirtileri."}],"Süpürge":[{name:"Elektrikli Süpürge",href:"/elektrikli-supurge-tamiri-konya/",summary:"Çekiş, motor, güç ve koku sorunları."}],"Küçük ev aletleri":[]};
const partsFor=(scope:string[])=>{const parts:string[]=[];if(scope.some(item=>["Çamaşır","Bulaşık","Kurutma"].includes(item)))parts.push("Kapak kilidi ve conta","Pompa, hortum ve filtre","Isıtıcı, rezistans veya termik","Elektronik kart ve program düğmesi");if(scope.includes("Buzdolabı")||scope.includes("Derin dondurucu")||scope.includes("Su sebili"))parts.push("Kapı contası ve menteşe","Fan motoru ve hava kanalı","Termostat, sensör ve kontrol kartı","Su giriş hortumu ve musluk grubu");if(scope.includes("Fırın/Ocak")||scope.includes("Davlumbaz"))parts.push("Isıtıcı rezistans ve termostat","Ateşleme bujisi ve düğme","Davlumbaz karbon filtresi","Motor ve aydınlatma bileşeni");if(scope.some(item=>["Süpürge","Küçük ev aletleri"].includes(item)))parts.push("Filtre ve toz haznesi kapağı","Motor, kablo ve anahtar","Fırça başlığı ve tekerlek","Şarj adaptörü ve batarya");return parts.filter((part,index)=>parts.indexOf(part)===index).slice(0,4)};
const maintenanceFor=(scope:string[]):CareTip[]=>[{title:"Temizliği aksatmayın",text:scope.some(item=>["Buzdolabı","Derin dondurucu","Su sebili"].includes(item))?"Hava kanalı, conta ve su temas eden yüzeyleri üretici talimatına uygun biçimde düzenli temizleyin.":"Filtre, conta ve görünür yüzeylerdeki birikintileri üretici talimatına uygun biçimde düzenli temizleyin."},{title:"Belirtiyi erken kaydedin",text:"Ses, koku, performans kaybı veya hata kodu fark ettiğinizde model bilgisiyle birlikte not alın; bu bilgi ön değerlendirmeyi kolaylaştırır."},{title:"Kullanım kılavuzunu izleyin",text:"Kapasite, temizlik ve güvenlik adımlarında cihazın modeline ait kullanım kılavuzundaki önerileri esas alın."}];
const brand=(name:string,image:string):Data=>{const scope=brandCoverage[name]??["Beyaz eşya","Küçük ev aletleri"];const devices=scope.join(", ");const seo=brandSeo[name];return {name,eyebrow:`KONYA ${name.toUpperCase()} CİHAZ SERVİSİ`,title:seo?.title??`Konya ${name} Servisi | Arıza, Parça ve Bakım Rehberi`,desc:seo?.description??`Konya’da ${name} marka ${devices.toLocaleLowerCase("tr-TR")} cihazları için arıza, bakım ve servis rehberini inceleyin.`,lead:`${name} marka ${devices.toLocaleLowerCase("tr-TR")} cihazınızda görülen arızayı, model bilgisini ve ilçenizi paylaşın; servis talebinizi birlikte netleştirelim.`,image,issues:[`${name} marka cihazlarda çalışma, başlatma veya hata kodu bildirimi`,`${name} cihazın türüne göre performans, ısıtma veya soğutma kaybı`,`Cihaz türüne göre normal dışı ses, titreşim, koku veya su sızıntısı`,`Model, hata kodu ve arızanın ne zaman başladığına ilişkin bilgiler`],copy:[`${name} marka cihazınız için doğru değerlendirme yapılabilmesi adına önce cihaz türünü, model bilgisini ve görülen belirtiyi netleştirmek gerekir. Aynı belirti; çamaşır makinesi, bulaşık makinesi, buzdolabı veya kurutma makinesinde farklı nedenlerden kaynaklanabilir.`,`Aşağıdaki cihaz rehberlerinden size uygun olanı seçerek cihaz türüne özel arıza belirtilerini inceleyebilirsiniz. Cihazın elektrik, gaz, su veya soğutma sistemini açarak müdahale etmeyin; yanık kokusu, kaçak veya sigorta attırma varsa kullanmayı bırakıp servis desteği alın.`],parts:partsFor(scope),faqs:[brandContent[name]?.faq??[`${name} cihazım için hangi bilgileri paylaşmalıyım?`,`Model bilgisini, arıza belirtisini, varsa hata kodunu ve bulunduğunuz ilçeyi yazmanız ilk yönlendirme için yeterlidir.`],...commonFaq]}};
Object.entries(brandPaths).forEach(([name,path],index)=>{pages[path]=brand(name,[img.wash,img.kitchen,img.hero,img.track][index%4])});

function meta(title:string,desc:string){useEffect(()=>{document.title=title;let m=document.querySelector('meta[name="description"]');if(!m){m=document.createElement("meta");m.setAttribute("name","description");document.head.append(m)}m.setAttribute("content",desc)},[title,desc])}
function Hero({d}:{d:Data}){const isBrand=Boolean(brandCoverage[d.name]);const alt=isBrand?`${d.name} marka cihazlar için Konya servis hizmeti`:deviceCoverage[d.name]?`${d.name} tamiri ve Konya teknik servis hizmeti`:`${d.name} bölgesinde beyaz eşya teknik servis hizmeti`;return <section className="inner-hero"><img className="inner-hero-image" src={d.image} width={1600} height={900} alt={alt} loading="eager" decoding="async" /><div className="inner-content"><nav className="breadcrumb"><a href="/">Ana Sayfa</a><ChevronRight size={13}/><span>{d.name}</span></nav><span className="hero-eyebrow"><i/>{d.eyebrow}</span><h1>{d.name}<br/><em>{isBrand?"servisi ve bakım rehberi.":"tamiri ve servis desteği."}</em></h1><p>{d.lead}</p><div className="hero-actions"><a className="button button-primary" target="_blank" rel="noreferrer" href={whatsappLink}><MessageCircle size={18}/>WhatsApp’tan Yazın</a><a className="button button-ghost button-form-hero" href="/#on-bilgi-formu"><Wrench size={17}/>Ön Bilgi Formu</a><a className="button button-ghost" href={contactPhoneHref}><Phone size={17}/>{contactPhone}</a></div></div></section>}
function TrackBox(){return <aside className="trackbox"><small><i className="live-dot"/>ONLINE İŞ TAKİBİ</small><h3>Servis kaydınız<br/>telefonunuzda.</h3><p>Size özel link, işlem başladığında WhatsApp üzerinden iletilir.</p><a href="/online-servis-takibi/">Takip sistemini inceleyin <ArrowRight size={15}/></a></aside>}
const deviceCoverage:Record<string,string[]>={"Çamaşır Makinesi":["Çamaşır"],"Bulaşık Makinesi":["Bulaşık"],"Kurutma Makinesi":["Kurutma"],"Fırın":["Fırın/Ocak"],"Ocak":["Fırın/Ocak"],"Buzdolabı":["Buzdolabı"],"Elektrikli Süpürge":["Süpürge","Küçük ev aletleri"],"Davlumbaz":["Davlumbaz"],"Derin Dondurucu":["Derin dondurucu"],"Su Sebili":["Su sebili"]};

function DistrictNeighborhoods({name}:{name:string}){const list=districtNeighborhoods[name]??[];if(!list.length)return null;return <section className="district-neighborhoods" aria-labelledby="district-neighborhoods-title"><div className="district-neighborhoods-heading"><span className="section-kicker">HİZMET VERDİĞİMİZ MAHALLELER</span><h2 id="district-neighborhoods-title">{name} ilçesinde<br/><em>hizmet verdiğimiz mahalleler.</em></h2><p>Mahallenizi listede bulamıyorsanız açık adresinizi WhatsApp’tan paylaşarak servis uygunluğunu öğrenebilirsiniz.</p></div><div className="neighborhood-list">{list.map((neighborhood,index)=><span key={neighborhood}><b>{String(index+1).padStart(2,"0")}</b>{neighborhood}</span>)}</div></section>}
 function BrandNudge(){const current=pages[window.location.pathname]?.name;const matching=current?deviceBrandLists[current]??[]:[];if(!matching.length)return null;const title=`${current} için hizmet verilen markalar`;return <section className="brand-nudge device-brand-nudge" aria-labelledby="brand-nudge-title"><div className="brand-nudge-head"><div><span className="section-kicker">HİZMET VERİLEN MARKALAR</span><h3 id="brand-nudge-title">{title}</h3></div><span className="brand-count">{matching.length} marka</span><p>Cihazınızın markasını seçin; model ve arıza bilgisini servis talebinize ekleyerek doğru yönlendirme alın.</p></div><div className="device-brand-grid">{matching.map((brand,index)=><a href={brandPaths[brand]} key={brand}><span className="brand-index">{String(index+1).padStart(2,"0")}</span><strong>{brand}</strong><span className="brand-card-link">Servis rehberini aç <ArrowRight size={14}/></span></a>)}</div><div className="brand-nudge-actions"><a href="/tum-markalar/">Tüm marka servislerini görün <ArrowRight size={15}/></a><a href="/#on-bilgi-formu">Ön Bilgi Formuna git <ArrowRight size={15}/></a></div></section>}
 function RelatedLinks({name}:{name:string}){const links=relatedLinks[name]??[];if(!links.length)return null;const isDistrict=["Karatay","Meram","Selçuklu"].includes(name);return <section className="related-links" aria-labelledby="related-links-title"><span className="section-kicker">BAĞLANTILI REHBERLER</span><h2 id="related-links-title">İlgili hizmetleri<br/><em>birlikte inceleyin.</em></h2><p>{isDistrict?`${name} bölgesinde sık ihtiyaç duyulan beyaz eşya servis rehberlerine hızlıca ulaşın.`:`${name} ile birlikte kullanılan veya benzer servis ihtiyacı doğurabilen cihazlar için ilgili rehberlere göz atın.`}</p><div>{links.map(link=><a href={link.href} key={link.href}><span>{link.name}</span><ArrowRight size={16}/></a>)}</div></section>}
function DeviceCare({d}:{d:Data}){if(!d.maintenance)return null;return <section className="device-care" aria-labelledby="device-care-title"><div className="device-care-heading"><span className="section-kicker">GÜVENLİ BAKIM VE SERVİS ÖNCESİ KONTROLLER</span><h2 id="device-care-title">Cihazınızı servise hazırlarken<br/><em>güvenli adımları izleyin.</em></h2><p>Basit gözlem ve bakım adımlarını cihazın kullanım kılavuzuna uygun biçimde uygulayın. Elektrik, gaz, soğutma veya motor bölümlerini açarak müdahale etmeyin.</p></div><div className="device-care-grid">{d.maintenance.map((tip,index)=><article key={tip.title}><span>{String(index+1).padStart(2,"0")}</span><div><h3>{tip.title}</h3><p>{tip.text}</p></div></article>)}</div></section>}
function BrandCare({d}:{d:Data}){const scope=brandCoverage[d.name]??[];const links=Array.from(new Map(scope.flatMap(tag=>brandDevicePaths[tag]??[]).map(item=>[item.href,item])).values());return <section className="brand-care" aria-labelledby="brand-care-title"><div className="brand-care-heading"><span className="section-kicker">MARKA VE CİHAZ REHBERİ</span><h2 id="brand-care-title">{d.name} cihazınızın türünü<br/><em>seçerek ilerleyin.</em></h2><p>{d.name} marka cihazlarda doğru arıza değerlendirmesi için önce cihaz türünü ve model bilgisini netleştirin. Aşağıdaki rehberler yalnızca ilgili cihaz grubuna ait belirtileri ve güvenli servis bilgilerini içerir.</p></div><div className="brand-device-guide-grid">{links.map((item,index)=><a href={item.href} key={item.href}><small>{String(index+1).padStart(2,"0")}</small><div><strong>{d.name} {item.name} Servisi</strong><span>{item.summary}</span></div><ArrowRight size={17}/></a>)}</div><p className="brand-safety-note"><ShieldCheck size={17}/>Cihaz türü netleşmeden parça veya teknik müdahale önerilmez. Yanık kokusu, su/gaz kaçağı veya sigorta attırma varsa cihazı kullanmayın.</p></section>}
function Guide({d}:{d:Data}){if(!d.guide)return null;const isDistrict=Boolean(districtNeighborhoods[d.name]);return <section className="service-guide-content" aria-labelledby="service-guide-content-title"><span className="section-kicker">{isDistrict?"İLÇE SERVİS REHBERİ":"CİHAZ SERVİS REHBERİ"}</span><h2 id="service-guide-content-title">{isDistrict?`${d.name} için servis sürecinde`: `${d.name} arızalarında`}<br/><em>{isDistrict?"bilmeniz gerekenler.":"bilmeniz gerekenler."}</em></h2>{d.guide.map(section=><article key={section.title}><h3>{section.title}</h3><p>{section.text}</p></article>)}</section>}
function FaqSchema({d}:{d:Data}){useEffect(()=>{if(!d.guide)return;document.getElementById("service-faq-schema")?.remove();const script=document.createElement("script");script.id="service-faq-schema";script.type="application/ld+json";script.text=JSON.stringify({"@context":"https://schema.org","@type":"FAQPage","mainEntity":d.faqs.map(([name,text])=>({"@type":"Question",name,acceptedAnswer:{"@type":"Answer",text}}))});document.head.append(script);return()=>document.getElementById("service-faq-schema")?.remove()},[d]);return null}
function Info({d}:{d:Data}){meta(d.title,d.desc);const isBrand=Boolean(brandCoverage[d.name]);const isDistrict=Boolean(districtNeighborhoods[d.name]);return <SiteChrome><FaqSchema d={d}/><Hero d={d}/><section className="detail-layout"><article><span className="section-kicker">{isDistrict?"BÖLGENİZDE SERVİS DESTEĞİ":"HANGİ DURUMLARDA ULAŞMALISINIZ?"}</span><h2>{isDistrict?`${d.name} bölgesinde`: `${d.name} ${isBrand?"servisinde":"tamir ve servisinde"}`}<br/><em>{isDistrict?"servis desteği alın.":"önce sorunu netleştirelim."}</em></h2>{!isBrand&&<p className="detail-lead">{d.lead}</p>}<ul className="issue-list">{d.issues.map(x=><li key={x}><Check size={17}/>{x}</li>)}</ul><div className="detail-copy">{d.copy.map(x=><p key={x}>{x}</p>)}</div>{!isDistrict&&<Guide d={d}/>}<DeviceCare d={d}/>{isBrand&&<BrandCare d={d}/>} {!isBrand&&!isDistrict&&<BrandNudge/>}{districtNeighborhoods[d.name]&&<DistrictNeighborhoods name={d.name}/>}<RelatedLinks name={d.name}/><section className="flow"><span className="section-kicker">{isDistrict?"İLÇEDE SERVİS SÜRECİ":"SERVİS SÜRECİ NASIL İŞLER?"}</span><div><article><b>01</b><h3>{isDistrict?"Cihaz ve adres bilgilerini paylaşın":"Cihaz ve arıza bilgisini paylaşın"}</h3><p>{isDistrict?"Cihaz türünü, marka-model bilgisini, arıza belirtisini ve açık adresinizi iletin.":"Cihazın markasını, modelini, arıza belirtisini ve ilçenizi iletin."}</p></article><article><b>02</b><h3>{isDistrict?"Uygun zamanı netleştirin":"Servis planını netleştirin"}</h3><p>{isDistrict?"Adres ve ekip uygunluğuna göre servis zamanı hakkında bilgi alın.":"Uygunluk ve işlem koşulları hakkında WhatsApp üzerinden bilgi alın."}</p></article><article><b>03</b><h3>Süreci takip edin</h3><p>Size iletilen özel bağlantıdan işlem durumunu görüntüleyin.</p></article></div></section><section className="page-faq"><span className="section-kicker">SIK SORULANLAR</span><h2>{isDistrict?`${d.name} bölgesinde servis hakkında kısa cevaplar`:"Tamir ve servis hakkında kısa cevaplar"}</h2>{d.faqs.map(([q,a])=><article className="faq-answer" key={q}><h3>{q}</h3><p>{a}</p></article>)}</section></article><aside className="details-side"><TrackBox/><a className="side-form-link" href="/#on-bilgi-formu"><Wrench size={22}/><span>ÖN BİLGİ FORMU</span><strong>Servis talebinizi<br/>3 adımda hazırlayın.</strong><ArrowRight size={17}/></a><div className="side-card"><ShieldCheck size={22}/><h3>Orijinal parça yaklaşımı</h3><p>Parça ihtiyacı belirlendiğinde tamir süreciyle ilgili açık bilgilendirme yapılır.</p></div><div className="side-card"><Clock3 size={22}/><h3>Aynı gün servis hedefi</h3><p>Konya içi günlük uygunluğa göre servis planlama bilgisi paylaşılır.</p></div></aside></section></SiteChrome>}
const simpleSeo:Record<string,{title:string;description:string}>={
  "ONLINE SERVİS TAKİBİ":{title:"Konya Online Servis Takibi | Eşli Teknik",description:"Konya teknik servis kaydınızın durumunu online takip edin. Eşli Teknik servis sürecinde WhatsApp ile iletilen özel bağlantıyı kullanın."},
  "HİZMET VERİLEN MARKALAR":{title:"Konya Beyaz Eşya Servis Markaları | Eşli Teknik",description:"Konya’da Eşli Teknik’in servis desteği sunduğu beyaz eşya ve küçük ev aleti markalarını inceleyin; cihazınız için WhatsApp’tan ulaşın."},
  "SIK SORULAN SORULAR":{title:"Konya Teknik Servis SSS | Eşli Teknik",description:"Konya beyaz eşya tamiri ve teknik servis hakkında sık sorulan soruların yanıtlarını; servis planı, WhatsApp iletişimi ve online takip bilgilerini inceleyin."},
  "İLETİŞİM":{title:"Konya Teknik Servis İletişim | Eşli Teknik",description:"Konya beyaz eşya tamiri ve teknik servis talebi için Eşli Teknik’e WhatsApp veya telefonla ulaşın. Karatay, Meram ve Selçuklu’ya servis planlayın."},
  "KVKK AYDINLATMA METNİ":{title:"KVKK Aydınlatma Metni | Eşli Teknik",description:"Eşli Teknik’in servis talebi ve iletişim süreçlerinde kişisel verilerin işlenmesine ilişkin KVKK aydınlatma metnini inceleyin."},
  "GİZLİLİK POLİTİKASI":{title:"Gizlilik Politikası | Eşli Teknik Konya",description:"Eşli Teknik web sitesinde, WhatsApp iletişiminde ve teknik servis talebi süreçlerinde gizlilik ve veri kullanımı hakkında bilgi alın."},
  "ÇEREZ POLİTİKASI":{title:"Çerez Politikası | Eşli Teknik Konya",description:"Eşli Teknik web sitesinde kullanılan çerezlerin amaçları, türleri ve çerez tercihlerinizi nasıl yönetebileceğiniz hakkında bilgi alın."},
  "SAYFA BULUNAMADI":{title:"Sayfa Bulunamadı | Eşli Teknik Konya",description:"Aradığınız sayfa bulunamadı. Eşli Teknik Konya teknik servis hizmetlerini incelemek veya servis talebi oluşturmak için ana sayfaya dönün."}
};
function Simple({kicker,title,text,children}:{kicker:string;title:ReactNode;text:string;children:ReactNode}){const seo=simpleSeo[kicker];meta(seo?.title??`${kicker} | EŞLİ TEKNİK`,seo?.description??text);return <SiteChrome><section className={`simple-hero ${kicker === "İLETİŞİM" ? "contact-hero" : kicker === "HAKKIMIZDA" ? "about-hero" : ""}`}><MapPin className="contact-hero-watermark" aria-hidden="true" strokeWidth={1.05}/><ShieldCheck className="about-hero-watermark" aria-hidden="true" strokeWidth={1.05}/><div><nav className="breadcrumb"><a href="/">Ana Sayfa</a><ChevronRight size={13}/><span>{kicker}</span></nav><span className="hero-eyebrow"><i/>{kicker}</span><h1>{title}</h1><p>{text}</p></div></section>{children}</SiteChrome>}
function Tracking(){const stages=[{label:"SERVİS KAYDI",title:"Talebiniz alınır",text:"Cihaz, arıza belirtisi ve ilçe bilginiz servis kaydına eklenir.",Icon:MessageCircle},{label:"PLANLAMA",title:"Uygun zaman paylaşılır",text:"Takvim uygunluğuna göre servis planı WhatsApp’tan bildirilir.",Icon:Clock3},{label:"TEKNİK İNCELEME",title:"Cihaz değerlendirilir",text:"Arıza tespiti ve gerekli işlem başlıkları kayıt altına alınır.",Icon:Wrench},{label:"ONARIM DURUMU",title:"Aşama güncellenir",text:"İşlem ve parça ihtiyacı netleştikçe takip bağlantınıza yansır.",Icon:MapPin},{label:"TESLİM",title:"Kayıt tamamlanır",text:"İşlem sonlandığında son durum ve teslim bilgisi takip ekranında görünür.",Icon:Check}];return <div className="tracking-page"><Simple kicker="ONLINE SERVİS TAKİBİ" title={<>Servis kaydınızın her adımı<br/><em>telefonunuzda görünür.</em></>} text="Servis kaydı açıldıktan sonra size WhatsApp üzerinden özel takip bağlantısı iletilir. Sürecin hangi aşamada olduğunu bu bağlantıdan kolayca takip edebilirsiniz."><section className="tracking-standard-layout" aria-labelledby="tracking-document-title"><article className="tracking-standard-document"><header className="tracking-standard-document-head"><span className="section-kicker">ONARIM AŞAMALARI</span><h2 id="tracking-document-title">Beş kısa adımda,<br/><em>süreç net kalsın.</em></h2><p>Takip bağlantınız; servis kaydının açılmasından teslim bilgisine kadar hangi aşamada olduğunuzu sade biçimde gösterir.</p></header><div className="tracking-standard-stages" role="list" aria-label="Onarım süreci aşamaları">{stages.map(({label,title,text,Icon},index)=><article role="listitem" key={label}><span>{String(index+1).padStart(2,"0")}</span><div><Icon size={21}/><small>{label}</small><h3>{title}</h3><p>{text}</p></div></article>)}</div><div className="tracking-standard-note"><span>ÖNEMLİ BİLGİ</span><p>Takip ekranı servis kaydınıza özeldir. Gerçek işlem durumu ve güncellemeler yalnızca kayıt oluşturulduktan sonra paylaşılır.</p></div></article><aside className="tracking-standard-aside"><div className="tracking-standard-status"><LayoutGrid size={25}/><span><small>TAKİP BAĞLANTISI</small><strong>WhatsApp’tan<br/>telefonunuza gelir.</strong></span></div><a className="tracking-standard-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small>TAKİP LİNKİNİZ Mİ KAYIP?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="tracking-standard-help"><Clock3 size={19}/><p>Henüz kaydınız yoksa cihaz, arıza ve ilçe bilginizi Ön Bilgi Formu üzerinden düzenli biçimde paylaşabilirsiniz.</p><a href="/#on-bilgi-formu">Ön Bilgi Formuna git <ArrowRight size={14}/></a></div></aside></section></Simple></div>}
function BrandDeviceIcon({brand}:{brand:string}){const coverage=brandCoverage[brand];if(coverage.some(tag=>["Çamaşır","Bulaşık","Kurutma"].includes(tag)))return <WashingMachine size={23}/>;if(coverage.includes("Fırın/Ocak"))return <Flame size={23}/>;if(coverage.includes("Davlumbaz"))return <Fan size={23}/>;if(coverage.some(tag=>["Buzdolabı","Derin dondurucu","Su sebili"].includes(tag)))return <Refrigerator size={23}/>;return <Gauge size={23}/>}
function Brands(){meta("Konya Beyaz Eşya Servis Markaları | Eşli Teknik","Konya’da Eşli Teknik’in servis desteği sunduğu 19 beyaz eşya ve küçük ev aleti markasını inceleyin. Marka ve cihazınıza göre servis rehberine ulaşın.");return <SiteChrome><section className="brand-page-hero"><img className="brand-page-hero-image" src={img.hero} width={1600} height={900} alt="Konya beyaz eşya servis markaları rehberi" loading="eager" decoding="async" /><div className="brand-page-hero-content"><nav className="breadcrumb"><a href="/">Ana Sayfa</a><ChevronRight size={13}/><span>Hizmet Verdiğimiz Markalar</span></nav><span className="hero-eyebrow"><i/>HİZMET VERDİĞİMİZ MARKALAR</span><h1>Markanız için doğru<br/><em>servis kapsamını bulun.</em></h1><p>Beyaz eşya ve küçük ev aletlerinde hizmet verdiğimiz 19 markanın cihaz kapsamını ve sık görülen arıza rehberlerini tek ekrandan inceleyin.</p><div className="brand-hero-stat"><strong>19</strong><span>marka için<br/>detaylı servis rehberi</span></div></div></section><section className="brand-directory"><header className="brand-directory-intro"><div><span className="section-kicker">MARKA SERVİS DİZİNİ</span><h2>Markanızı seçin,<br/><em>arıza sürecini inceleyin.</em></h2><p>Her kartta cihaz kapsamını, sık karşılaşılan arıza belirtilerini ve ilgili marka için hazırlanan servis rehberini bulabilirsiniz.</p></div></header><div className="brand-directory-grid">{brands.map((brand,index)=><a className="brand-directory-card" href={brandPaths[brand]} key={brand}><span className="brand-directory-icon"><BrandDeviceIcon brand={brand}/></span><small>{String(index+1).padStart(2,"0")}</small><strong>{brand}</strong><p>{brandCoverage[brand].join(" · ")}</p><em>Arıza ve onarım rehberi <ArrowRight size={15}/></em></a>)}</div></section></SiteChrome>}
const questions=[["İş takip linki nedir, nasıl çalışır?","Servis kaydınız açıldıktan sonra WhatsApp üzerinden size özel bir bağlantı iletilir. Bu bağlantı üzerinden kaydınıza ait güncellemeleri takip edebilirsiniz."],["Cihazımın tamir durumunu nasıl öğrenirim?","Size gönderilen takip linkini telefonunuzdan açarak son durum bilgisini görüntüleyebilirsiniz."],["Takip linkim kayboldu, ne yapmalıyım?","WhatsApp üzerinden bize yazın; kayıt doğrulamasından sonra bağlantınız yeniden paylaşılabilir."],["Hangi ilçelere servis veriyorsunuz?","Karatay, Meram ve Selçuklu için servis planlaması hakkında WhatsApp’tan bilgi alabilirsiniz."],["Klima veya kombi servisi veriyor musunuz?","Hayır. Servisimiz beyaz eşya ve küçük ev aletlerine odaklanır; klima ve kombi konusunda uzmanlaşmış firmalara yönlendirmekten çekinmeyiz."],["Resmî yetkili servis misiniz?","EŞLİ TEKNİK bağımsız bir teknik servis olarak hizmet kapsamını değerlendirir. Resmî yetkili servis iddiası yapmaz."]];
function About(){return <div className="about-page tracking-page"><Simple kicker="HAKKIMIZDA" title={<>Konya’da teknik servis<br/><em>anlayışımız.</em></>} text="Eşli Teknik olarak beyaz eşya ve küçük ev aletleri servis süreçlerini açık, güvenli ve takip edilebilir hale getirmek için çalışıyoruz."><section className="tracking-standard-layout about-standard-layout" aria-labelledby="about-document-title"><article className="tracking-standard-document about-standard-document"><header className="tracking-standard-document-head"><span className="section-kicker">EŞLİ TEKNİK HAKKINDA</span><h2 id="about-document-title">Arızadan çözüme,<br/><em>süreç net kalsın.</em></h2><p>EŞLİ TEKNİK; Karatay, Meram ve Selçuklu başta olmak üzere Konya’da beyaz eşya ve küçük ev aletleri için teknik servis desteği sunar. Amacımız yalnızca cihazı onarmak değil; servis planını, inceleme kapsamını ve işlem sonrasını anlaşılır biçimde paylaşmaktır.</p></header><div className="tracking-standard-stages about-standard-stages" role="list" aria-label="Eşli Teknik çalışma yaklaşımı"><article role="listitem"><span>01</span><div><ShieldCheck size={21}/><small>ŞEFFAF İLETİŞİM</small><h3>Ne yapılacağını bilirsiniz</h3><p>Arıza belirtisi, inceleme kapsamı ve gerekli işlem başlıklarını açık biçimde paylaşırız.</p></div></article><article role="listitem"><span>02</span><div><Clock3 size={21}/><small>PLANLI SERVİS</small><h3>Servis süreci planlanır</h3><p>İlçe, cihaz ve uygunluk bilgisine göre servis zamanını netleştiririz.</p></div></article><article role="listitem"><span>03</span><div><MessageCircle size={21}/><small>KOLAY ULAŞIM</small><h3>Doğrudan iletişim kurarsınız</h3><p>WhatsApp veya telefon üzerinden cihaz ve arıza bilgilerinizi kolayca iletebilirsiniz.</p></div></article></div><div className="tracking-standard-note about-service-area-card"><div className="about-area-card-head"><div className="about-area-card-icon"><MapPin size={22}/></div><div><span>HİZMET BÖLGEMİZ</span><strong>Konya’nın merkez ilçelerinde<br/>yanınızdayız.</strong></div></div><p>Karatay, Meram ve Selçuklu ilçelerinde servis planlaması yapıyoruz. Talebinizde mahalle, marka-model ve arıza bilgisini paylaşmanız doğru yönlendirmeyi hızlandırır.</p><div className="about-area-list"><span><b>01</b><MapPin size={16}/>Karatay</span><span><b>02</b><MapPin size={16}/>Meram</span><span><b>03</b><MapPin size={16}/>Selçuklu</span></div></div></article><aside className="tracking-standard-aside"><div className="tracking-standard-status"><ShieldCheck size={25}/><span><small>ÇALIŞMA YAKLAŞIMIMIZ</small><strong>Açık, planlı ve<br/>takip edilebilir.</strong></span></div><a className="tracking-standard-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small>SERVİS DESTEĞİ Mİ GEREKİYOR?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="tracking-standard-help"><MapPin size={19}/><p>Gaziosmanpaşa Mah. Menzil Cad. No:70, Karatay / Konya adresinden Karatay, Meram ve Selçuklu için servis planlaması yapılır.</p><a href="/iletisim/">İletişim sayfasına git <ArrowRight size={14}/></a></div></aside></section></Simple></div>}
function Faq(){return <div className="faq-page"><Simple kicker="SIK SORULAN SORULAR" title={<>Önce sorularınızı<br/><em>netleştirelim.</em></>} text="Servis kaydı, online takip sistemi ve hizmet kapsamı hakkında en sık gelen soruların kısa cevapları burada."><section className="all-faq"><div>{questions.map(([q,a],i)=><details key={q} open={i===0}><summary><small>0{i+1}</small>{q}<ChevronDown size={18}/></summary><p>{a}</p></details>)}</div><TrackBox/></section></Simple></div>}
function Contact(){return <div className="contact-page"><Simple kicker="İLETİŞİM" title={<>Arızayı yazın,<br/><em>servis planını konuşalım.</em></>} text="Konya’da Karatay, Meram ve Selçuklu için beyaz eşya ve küçük ev aletleri servis talebinizi WhatsApp’tan doğrudan oluşturabilirsiniz."><section className="contact"><div className="contact-map-wrap"><div className="contact-map"><iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1873.1467206271639!2d32.53197597271406!3d37.854563873282345!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x619e929968b31de5%3A0x22136250a2b09569!2sE%C5%9Fli%20Teknik%20-%20Konya%20Beyaz%20E%C5%9Fya%20Servisi!5e0!3m2!1str!2str!4v1788974359452!5m2!1str!2str" title="Eşli Teknik Konya servis konumu" loading="lazy" referrerPolicy="strict-origin-when-cross-origin" allowFullScreen /></div></div><div className="contact-cards"><a href={contactPhoneHref}><Phone/><span><small>TELEFON</small><b>{contactPhone}</b><em>Her gün 08:00–22:00</em></span><ArrowRight/></a><div><MapPin/><span><small>ADRES</small><b>Gaziosmanpaşa Mah. Menzil Cad. No:70</b><em>Karatay / Konya</em></span></div><a href={`mailto:${contactEmail}`}><Mail/><span><small>E-POSTA</small><b>{contactEmail}</b><em>Yazılı iletişim için</em></span><ArrowRight/></a><div><MapPin/><span><small>HİZMET BÖLGESİ</small><b>Karatay · Meram · Selçuklu</b><em>Konya içi servis planlaması</em></span></div><div><Clock3/><span><small>ÇALIŞMA SAATLERİ</small><b>Her gün 08:00–22:00</b><em>Uygunluğu WhatsApp’tan sorun</em></span></div></div></section></Simple></div>}
function Blog(){let posts=["Konya’da kış aylarında buzdolabı neden fazla dondurur?","Çamaşır makinesi su almıyorsa evde hangi kontroller güvenle yapılabilir?","Selçuklu’da bulaşık makinesi kokusu için ilk bakım adımları","Meram’da ankastre fırın geç ısınıyorsa neye dikkat edilmeli?","Karatay’da robot süpürge şarj olmuyorsa ilk kontrol listesi","Buzdolabından gelen sesler ne zaman teknik servis gerektirir?","Çamaşır makinesi sıkmıyorsa çamaşır dağılımı neden önemlidir?","Bulaşık makinesinde su kalması ne anlama gelebilir?","Yaz aylarında buzdolabı kullanımı: Kapak contası ve havalandırma","Küçük ev aletlerini uzun süre kullanmak için temizlik önerileri"];return <Simple kicker="BİLGİ MERKEZİ" title={<>Cihazınızın dilini<br/><em>birlikte anlayalım.</em></>} text="Konya’daki evlerde sık karşılaşılan beyaz eşya ve küçük ev aleti sorunları için pratik, güvenli ve anlaşılır içerikler."><section className="blog"><div><span className="section-kicker">İLK 10 KONU</span><h2>Mevsime ve kullanıma<br/><em>göre teknik notlar.</em></h2></div><div>{posts.map((x,i)=><article key={x}><small>0{i+1}</small><span><em>{i<5?"BAKIM VE KULLANIM":"ARIZA BELİRTİLERİ"}</em><h3>{x}</h3></span><button aria-label={`${x} yazısı yakında gelecek`}><ArrowRight size={19}/></button></article>)}</div></section></Simple>}
function Legal({type}:{type:string}) {
  const isKvkk = type === "KVKK Aydınlatma Metni";
  if (!isKvkk) return <Simple kicker={type.toUpperCase()} title={<>{type}<br/><em>genel bilgilendirmesi.</em></>} text="Bu metin, Konya Teknik Servis ile iletişim ve hizmet sürecindeki temel ilkeleri açıklamak için hazırlanmıştır."><section className="legal"><p className="notice">İşletmenin resmi unvanı, açık adresi, MERSİS/vergi bilgileri ve veri sorumlusu bilgileri yayın öncesinde doğrulanarak bu metne eklenmelidir.</p><h2>1. Kapsam</h2><p>Bu bilgilendirme, telefon veya WhatsApp üzerinden iletilen servis talepleri sırasında paylaşılan iletişim ve cihaz bilgilerine ilişkin genel yaklaşımı kapsar.</p><h2>2. İletişim ve servis kaydı</h2><p>İletişim bilgileri, talebin değerlendirilmesi, servis planlaması, güncelleme paylaşımı ve yasal yükümlülüklerin yerine getirilmesi amaçlarıyla işlenebilir.</p><h2>3. Online iş takibi</h2><p>Servis kaydına özel takip bağlantısı yalnızca ilgili müşteriye WhatsApp üzerinden iletilir. Bağlantının güvenliği için üçüncü kişilerle paylaşılmaması gerekir.</p></section></Simple>;
  const sections = [
    { title: "Veri Sorumlusu", paragraphs: ["6698 sayılı Kişisel Verilerin Korunması Kanunu (\"KVKK\") kapsamında kişisel verileriniz, veri sorumlusu sıfatıyla Eşli Teknik tarafından işlenmektedir."], contact: ["Yetkili: Mevlüt Esad EŞLİ", "Telefon: 0 551 185 87 73", "E-posta: bilgi@esliteknik.com"] },
    { title: "İşlenen Kişisel Veriler", paragraphs: ["Web sitemiz ve iletişim kanallarımız üzerinden bizimle iletişime geçmeniz halinde aşağıdaki kişisel verileriniz işlenebilmektedir:"], items: ["Ad ve soyad bilgisi", "Telefon numarası", "WhatsApp iletişim bilgileri", "Servis talebiniz ile ilgili açıklamalar", "Servis hizmetinin gerçekleştirileceği adres bilgisi", "İletişim süreçlerine ilişkin bilgiler"] },
    { title: "Kişisel Verilerin İşlenme Amaçları", paragraphs: ["Kişisel verileriniz aşağıdaki amaçlarla işlenmektedir:"], items: ["Teknik servis talebinizin alınması", "Beyaz eşya arıza bildiriminizin değerlendirilmesi", "Sizinle iletişim kurulması", "Servis hizmetinin planlanması", "Teknisyen yönlendirilmesi", "Müşteri memnuniyetinin sağlanması", "Hizmet süreçlerinin yürütülmesi", "Yasal yükümlülüklerin yerine getirilmesi"] },
    { title: "Kişisel Verilerin Toplanma Yöntemi ve Hukuki Sebebi", paragraphs: ["Kişisel verileriniz aşağıdaki iletişim kanalları aracılığıyla elektronik ortamda veya sözlü olarak toplanabilmektedir:"], items: ["Web sitemizde yer alan iletişim kanalları", "WhatsApp iletişim hattı", "Telefon görüşmeleri"], after: "Kişisel verileriniz; bir sözleşmenin kurulması veya ifasıyla doğrudan ilgili olması, veri sorumlusunun hukuki yükümlülüklerini yerine getirmesi ve veri sorumlusunun meşru menfaatleri hukuki sebeplerine dayanılarak işlenmektedir." },
    { title: "Kişisel Verilerin Aktarılması", paragraphs: ["Kişisel verileriniz; teknik servis hizmetinin gerçekleştirilebilmesi amacıyla Eşli Teknik bünyesinde görev yapan yetkili personel ile ve kanunen yetkili kamu kurum ve kuruluşları ile mevzuata uygun şekilde paylaşılabilir."] },
    { title: "Kişisel Verilerin Saklanması", paragraphs: ["Kişisel verileriniz, işlenme amacı için gerekli süre boyunca ve ilgili mevzuatta öngörülen saklama süreleri dikkate alınarak muhafaza edilir.", "Saklama süresinin sona ermesi halinde kişisel verileriniz silinir, yok edilir veya anonim hale getirilir."] },
    { title: "İlgili Kişinin Hakları", paragraphs: ["KVKK'nın 11. maddesi kapsamında kişisel verilerinizle ilgili olarak aşağıdaki haklara sahipsiniz:"], items: ["Kişisel verilerinizin işlenip işlenmediğini öğrenme", "İşlenmişse buna ilişkin bilgi talep etme", "İşlenme amacını ve amaca uygun kullanılıp kullanılmadığını öğrenme", "Aktarıldığı üçüncü kişileri bilme", "Eksik veya yanlış işlenmişse düzeltilmesini isteme", "Kanuni şartlar oluştuğunda silinmesini veya yok edilmesini isteme", "İşlenen verilerin münhasıran otomatik sistemler ile analiz edilmesi sonucunda aleyhinize bir sonuç ortaya çıkmasına itiraz etme", "Kanuna aykırı işlenmesi sebebiyle zarara uğramanız halinde zararınızın giderilmesini talep etme"] },
    { title: "Başvuru", paragraphs: ["KVKK kapsamındaki taleplerinizi Eşli Teknik'e yazılı olarak veya mevzuatta belirtilen diğer yöntemlerle iletebilirsiniz.", "Başvurularınız ilgili mevzuat kapsamında değerlendirilerek sonuçlandırılır."] }
  ];
  return <div className="kvkk-page"><Simple kicker="KVKK AYDINLATMA METNİ" title={<>Kişisel verileriniz için<br/><em>açık ve anlaşılır bilgilendirme.</em></>} text="EŞLİ TEKNİK ile servis talebi oluştururken paylaşılan bilgilerin hangi amaçlarla işlendiğine ilişkin temel açıklamalar burada yer alır."><section className="legal legal-layout" aria-labelledby="kvkk-document-title"><article className="legal-document"><header className="legal-document-head"><span className="section-kicker">KİŞİSEL VERİLERİN KORUNMASI</span><h2 id="kvkk-document-title">Aydınlatma metni,<br/><em>bilgi sahibi olmanız için.</em></h2><p>Servis planlaması ve iletişim sırasında gerekli kişisel verilerin hangi kapsamda işlendiğini, nasıl korunduğunu ve haklarınızı sade bir dille açıklıyoruz.</p></header><div className="legal-sections">{sections.map((section,index)=><section key={section.title}><span>{String(index+1).padStart(2,"0")}</span><div><h3>{section.title}</h3>{section.paragraphs?.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{section.contact&&<div className="legal-contact-strip">{section.contact.map(item=><span key={item}>{item}</span>)}</div>}{section.items&&<ul>{section.items.map(item=><li key={item}>{item}</li>)}</ul>}{section.after&&<p>{section.after}</p>}</div></section>)}</div></article><aside className="legal-aside"><div className="legal-status"><ShieldCheck size={25}/><span><small>KVKK BİLGİLENDİRMESİ</small><strong>Veri süreçleriyle ilgili<br/>temel bilgiler bu sayfada.</strong></span></div><a className="legal-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small>SORUNUZ MU VAR?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="legal-note"><Clock3 size={19}/><p>Servis talebiniz için cihaz, arıza ve ilçe bilginizi Ön Bilgi Formu üzerinden düzenli biçimde paylaşabilirsiniz.</p><a href="/#on-bilgi-formu">Ön Bilgi Formuna git <ArrowRight size={14}/></a></div></aside></section></Simple></div>
}function Privacy(){
  const sections=[
    {title:"Genel Bilgilendirme",paragraphs:["Eşli Teknik olarak ziyaretçilerimizin ve müşterilerimizin gizliliğine önem vermekteyiz.","Bu Gizlilik Politikası, www.esliteknik.com internet sitesini ziyaret eden kullanıcıların gizliliğinin korunması, internet sitesi kullanım süreçleri ve kullanıcı bilgilerinin nasıl değerlendirildiği hakkında bilgi vermek amacıyla hazırlanmıştır.","Web sitemizi ziyaret ederek veya iletişim kanallarımız aracılığıyla bizimle iletişime geçerek bu Gizlilik Politikası'nda belirtilen uygulamaları kabul etmiş olursunuz."]},
    {title:"Toplanan Bilgiler",paragraphs:["Web sitemizi ziyaret ettiğinizde veya Eşli Teknik ile iletişime geçtiğinizde aşağıdaki bilgiler işlenebilmektedir:"],items:["Ad ve soyad bilgisi","Telefon numarası","WhatsApp iletişim bilgileri","Servis talebiniz ile ilgili açıklamalar","Hizmet adresi bilgileri","Web sitesinin kullanımına ilişkin teknik bilgiler"],after:"Kullanıcılarımızdan yalnızca sunulan teknik servis hizmetlerinin yürütülmesi için gerekli olan bilgiler talep edilmektedir."},
    {title:"Bilgilerin Kullanım Amaçları",paragraphs:["Toplanan bilgiler aşağıdaki amaçlarla kullanılmaktadır:"],items:["Teknik servis taleplerinin alınması","Kullanıcılarla iletişim kurulması","Arıza bildiriminin değerlendirilmesi","Servis hizmetinin planlanması","Teknisyen yönlendirilmesi","Müşteri memnuniyetinin sağlanması","Hizmet kalitesinin geliştirilmesi","Yasal yükümlülüklerin yerine getirilmesi"]},
    {title:"WhatsApp İletişimi Hakkında",paragraphs:["Web sitemizde yer alan WhatsApp iletişim bağlantısı üzerinden bizimle iletişime geçebilirsiniz.","WhatsApp üzerinden tarafımıza ilettiğiniz bilgiler, servis talebinizin değerlendirilmesi ve teknik servis hizmetinin sağlanması amacıyla kullanılmaktadır.","WhatsApp hizmeti, üçüncü taraf bir iletişim platformu tarafından sağlanmaktadır. Bu platform üzerinden gerçekleştirilen iletişimlerde ilgili platformun kendi gizlilik politikaları da geçerlidir."]},
    {title:"Kişisel Bilgilerin Korunması",paragraphs:["Eşli Teknik, kullanıcı bilgilerinin güvenliğini sağlamak amacıyla gerekli teknik ve idari tedbirleri almaktadır."],items:["Yetkisiz erişime karşı korunur","Hizmet amacı dışında kullanılmaz","Kanuni zorunluluklar dışında üçüncü kişilerle paylaşılmaz"]},
    {title:"Bilgilerin Paylaşılması",paragraphs:["Kullanıcı bilgileriniz aşağıdaki kişi ve kuruluşlarla mevzuata uygun şekilde paylaşılabilir:"],items:["Teknik servis hizmetinin gerçekleştirilebilmesi için yetkili Eşli Teknik personeliyle","Kanunen yetkili kamu kurum ve kuruluşlarıyla","Hizmetin yerine getirilmesi için gerekli olması halinde ilgili hizmet sağlayıcılarla"],after:"Kişisel bilgileriniz hiçbir şekilde satılmaz veya ticari amaçlarla üçüncü kişilere aktarılmaz."},
    {title:"Web Sitesi Kullanımı ve Teknik Veriler",paragraphs:["Web sitemizi ziyaret ettiğinizde IP adresi, tarayıcı bilgileri, ziyaret zamanı ve ziyaret edilen sayfalar gibi teknik veriler güvenlik, performans ölçümü ve kullanıcı deneyiminin geliştirilmesi amacıyla işlenebilir.","Bu bilgiler, kullanıcı kimliğini doğrudan belirlemek amacıyla kullanılmaz."]},
    {title:"Çerezler (Cookies)",paragraphs:["Web sitemizde kullanıcı deneyimini geliştirmek, sitenin güvenli ve etkin şekilde çalışmasını sağlamak amacıyla çerezlerden yararlanılabilir.","Çerez kullanımı hakkında ayrıntılı bilgi için Çerez Politikası metnimizi inceleyebilirsiniz."]},
    {title:"Üçüncü Taraf Bağlantıları",paragraphs:["Web sitemizde kullanıcıların faydalanması amacıyla üçüncü taraf platformlara yönlendiren bağlantılar bulunabilir.","Bu bağlantılar üzerinden erişilen internet sitelerinin gizlilik uygulamalarından Eşli Teknik sorumlu değildir. Kullanıcıların, ziyaret ettikleri üçüncü taraf internet sitelerinin gizlilik politikalarını incelemeleri önerilir."]},
    {title:"Politika Değişiklikleri",paragraphs:["Eşli Teknik, gerekli gördüğü durumlarda bu Gizlilik Politikası üzerinde değişiklik yapabilir.","Güncellenen politika, www.esliteknik.com adresinde yayınlandığı tarihten itibaren geçerli olur."]},
    {title:"İletişim",paragraphs:["Gizlilik Politikası hakkında sorularınız veya talepleriniz için aşağıdaki iletişim kanallarından bizimle iletişime geçebilirsiniz."],contact:["Eşli Teknik / Mevlüt Esad EŞLİ","Telefon: 0 551 185 87 73","E-posta: bilgi@esliteknik.com","Web: www.esliteknik.com"]}
  ];
  return <div className="privacy-page"><Simple kicker="GİZLİLİK POLİTİKASI" title={<>Gizliliğiniz için<br/><em>açık ve anlaşılır yaklaşım.</em></>} text="EŞLİ TEKNİK web sitesini ziyaret ederken ve teknik servis talebi oluştururken bilgilerinizin nasıl değerlendirildiğine ilişkin temel açıklamalar burada yer alır."><section className="legal legal-layout" aria-labelledby="privacy-document-title"><article className="legal-document"><header className="legal-document-head"><span className="section-kicker">GİZLİLİK VE BİLGİ GÜVENLİĞİ</span><h2 id="privacy-document-title">Bilgileriniz hakkında<br/><em>şeffaf bilgilendirme.</em></h2><p>Web sitesi kullanımı, WhatsApp iletişimi ve teknik servis süreçlerinde hangi bilgilerin işlenebileceğini ve nasıl değerlendirildiğini sade bir dille açıklıyoruz.</p></header><div className="legal-sections">{sections.map((section,index)=><section key={section.title}><span>{String(index+1).padStart(2,"0")}</span><div><h3>{section.title}</h3>{section.paragraphs?.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{section.items&&<ul>{section.items.map(item=><li key={item}>{item}</li>)}</ul>}{section.after&&<p>{section.after}</p>}{section.contact&&<div className="legal-contact-strip">{section.contact.map(item=><span key={item}>{item}</span>)}</div>}</div></section>)}</div></article><aside className="legal-aside"><div className="legal-status"><ShieldCheck size={25}/><span><small>GİZLİLİK BİLGİLENDİRMESİ</small><strong>Bilgilerinizin kullanımıyla<br/>ilgili temel çerçeve.</strong></span></div><a className="legal-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small>GİZLİLİK SORUNUZ MU VAR?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="legal-note"><Clock3 size={19}/><p>Servis talebiniz için yalnızca hizmet planlaması ve iletişim bakımından gerekli bilgileri paylaşmanızı öneririz.</p><a href="/kvkk/">KVKK Aydınlatma Metni <ArrowRight size={14}/></a></div></aside></section></Simple></div>
}
function CookiePolicy(){
  const sections=[
    {title:"Çerez Nedir?",paragraphs:["Çerezler, bir internet sitesini ziyaret ettiğinizde tarayıcınız aracılığıyla cihazınıza kaydedilen küçük metin dosyalarıdır. Bu dosyalar, sitenin temel işlevlerini yerine getirmesine, tercihlerinizi hatırlamasına ve kullanım deneyiminin geliştirilmesine yardımcı olabilir.","Bu politika, Eşli Teknik web sitesinde çerezlerin ve benzer teknolojilerin hangi amaçlarla kullanılabileceğini açıklamak için hazırlanmıştır."]},
    {title:"Kullanılan Çerez Türleri",paragraphs:["Web sitemizde kullanım amacına ve saklama süresine göre farklı çerez türleri kullanılabilir:"],items:["Zorunlu çerezler: Sitenin güvenli ve doğru şekilde çalışması için gerekli olan çerezlerdir. Bu çerezler devre dışı bırakılamaz.","İşlevsel çerezler: Dil, görüntüleme veya tercih gibi seçimlerin hatırlanmasına yardımcı olan çerezlerdir.","Performans ve analiz çerezleri: Sitenin nasıl kullanıldığını anlamak, performansı ölçmek ve sayfaları geliştirmek amacıyla kullanılabilecek çerezlerdir.","Üçüncü taraf çerezleri: WhatsApp gibi üçüncü taraf hizmetlere yönlendiren bağlantılar veya gömülü hizmetler tarafından, kendi politikaları kapsamında yerleştirilebilecek çerezlerdir."]},
    {title:"Çerezlerin Kullanım Amaçları",paragraphs:["Çerezler, aşağıdaki amaçlarla kullanılabilir:"],items:["Web sitesinin temel işlevlerini ve güvenlik kontrollerini sağlamak","Sayfa tercihlerini ve oturumla ilgili teknik bilgileri hatırlamak","Ziyaretçi deneyimini ve site performansını değerlendirmek","İçerik ve hizmetleri daha anlaşılır, erişilebilir ve kullanışlı hale getirmek","Hataları tespit etmek ve teknik altyapının güvenilirliğini artırmak"]},
    {title:"Hangi Bilgiler İşlenebilir?",paragraphs:["Çerezler aracılığıyla tarayıcı türü, cihaz ve işletim sistemi bilgisi, ziyaret edilen sayfalar, ziyaret zamanı, yaklaşık kullanım ve etkileşim bilgileri gibi teknik veriler işlenebilir. Bu bilgiler, tek başına veya diğer verilerle birlikte kişiyi belirleyebilecek nitelikte olduğunda KVKK kapsamındaki yükümlülükler dikkate alınır.","Çerezler üzerinden elde edilen bilgiler, servis talebinin yürütülmesi için gerekli olmayan kişisel bilgilerin yerine geçmez. Servis talebi sırasında paylaştığınız ad, telefon ve adres bilgileri hakkında ayrıntılı bilgi için KVKK Aydınlatma Metni'ni inceleyebilirsiniz."]},
    {title:"Çerez Tercihlerinizi Yönetme",paragraphs:["Tarayıcı ayarlarınız üzerinden çerezleri kabul edebilir, reddedebilir veya daha önce kaydedilmiş çerezleri silebilirsiniz. Zorunlu çerezleri engellemeniz halinde sitenin bazı işlevleri beklenildiği gibi çalışmayabilir.","Çerez yönetimi adımları tarayıcıya göre değişebilir. Kullandığınız tarayıcının yardım veya gizlilik ayarları bölümünden çerez tercihlerinizi güncelleyebilirsiniz."]},
    {title:"Üçüncü Taraf Hizmetler",paragraphs:["Web sitemizde yer alan WhatsApp iletişim bağlantısı gibi üçüncü taraf hizmetlere yönlendirmeler bulunabilir. Bu hizmetlerin kendi çerez ve gizlilik uygulamaları Eşli Teknik'ten bağımsızdır. İlgili hizmetleri kullanmadan önce üçüncü taraf sağlayıcının güncel politikalarını incelemeniz önerilir."]},
    {title:"Politika Değişiklikleri",paragraphs:["Eşli Teknik, web sitesindeki teknik veya hukuki gelişmelere bağlı olarak bu Çerez Politikası'nı güncelleyebilir. Güncel metin bu sayfada yayınlandığı tarihte geçerli olur."]},
    {title:"İletişim",paragraphs:["Çerez Politikası hakkında sorularınız veya talepleriniz için bizimle iletişime geçebilirsiniz."],contact:["Eşli Teknik / Mevlüt Esad EŞLİ","Telefon: 0 551 185 87 73","Web: www.esliteknik.com"]}
  ];
  return <div className="kvkk-page cookie-page"><Simple kicker="ÇEREZ POLİTİKASI" title={<>Çerez kullanımı için<br/><em>açık ve anlaşılır bilgilendirme.</em></>} text="EŞLİ TEKNİK web sitesinde çerezlerin ve benzer teknolojilerin hangi amaçlarla kullanılabileceğine ilişkin temel açıklamalar burada yer alır."><section className="legal legal-layout" aria-labelledby="cookie-document-title"><article className="legal-document"><header className="legal-document-head"><span className="section-kicker">ÇEREZLER VE TEKNİK VERİLER</span><h2 id="cookie-document-title">Tercihleriniz için<br/><em>şeffaf bilgilendirme.</em></h2><p>Çerezlerin ne olduğunu, hangi amaçlarla kullanılabileceğini ve tarayıcı ayarlarınız üzerinden tercihlerinizi nasıl yönetebileceğinizi sade bir dille açıklıyoruz.</p></header><div className="legal-sections">{sections.map((section,index)=><section key={section.title}><span>{String(index+1).padStart(2,"0")}</span><div><h3>{section.title}</h3>{section.paragraphs?.map(paragraph=><p key={paragraph}>{paragraph}</p>)}{section.items&&<ul>{section.items.map(item=><li key={item}>{item}</li>)}</ul>}{section.contact&&<div className="legal-contact-strip">{section.contact.map(item=><span key={item}>{item}</span>)}</div>}</div></section>)}</div></article><aside className="legal-aside"><div className="legal-status"><ShieldCheck size={25}/><span><small>ÇEREZ BİLGİLENDİRMESİ</small><strong>Çerez tercihleriyle ilgili<br/>temel bilgiler bu sayfada.</strong></span></div><a className="legal-contact" href={whatsappLink} target="_blank" rel="noreferrer"><MessageCircle size={20}/><span><small> SORUNUZ MU VAR?</small><strong>WhatsApp’tan yazın</strong></span><ArrowRight size={16}/></a><div className="legal-note"><Clock3 size={19}/><p>Çerez ayarlarınızı kullandığınız tarayıcının gizlilik ve site ayarları bölümünden yönetebilirsiniz.</p><a href="/gizlilik-politikasi/">Gizlilik Politikası <ArrowRight size={14}/></a></div></aside></section></Simple></div>
}
export default function ContentPage({path}:{path:string}){if(pages[path])return <Info d={pages[path]}/>;if(path==="/online-servis-takibi/")return <Tracking/>;if(path==="/tum-markalar/")return <Brands/>;if(path==="/sss/")return <Faq/>;if(path==="/iletisim/")return <Contact/>;if(path==="/hakkimizda/")return <About/>;if(path==="/kvkk/")return <Legal type="KVKK Aydınlatma Metni"/>;if(path==="/gizlilik-politikasi/")return <Privacy/>;if(path==="/cerez-politikasi/")return <CookiePolicy/>;return <Simple kicker="SAYFA BULUNAMADI" title={<>Aradığınız sayfa<br/><em>burada değil.</em></>} text="Ana sayfaya dönerek hizmetleri inceleyebilir veya WhatsApp’tan servis talebi oluşturabilirsiniz."><p className="not-found-link"><a href="/"><ArrowRight size={18}/>Ana sayfaya dönün</a></p></Simple>}
